STATEMENT_SHA = json.loads(
    Path(__file__).with_name("botay_2025_ai_solutions_sha.json").read_text(encoding="utf-8")
)
MARKER = "Решение ИИ по исходному условию; требуется проверка."


def run(con: sqlite3.Connection, *, write: bool = False) -> int:
    count = 0
    for (variant, number), body in SOLUTIONS.items():
        row = con.execute("""SELECT p.id,p.statement,p.solution,p.review_notes FROM problems p
            JOIN variants v ON v.id=p.variant_id WHERE v.exam_year=2025
            AND v.variant_number=? AND p.problem_number=? AND p.alternative_number=1""",
            (variant, number)).fetchone()
        if not row:
            raise ValueError(f"Missing {variant} №{number}")
        pid, statement, current, notes = row
        if hashlib.sha256(statement.encode()).hexdigest()[:16] != STATEMENT_SHA[f"{variant}|{number}"]:
            print(f"Skip changed {variant} №{number} solution")
            continue
        owned = "solution: редакция ИИ по исходному условию" in (notes or "")
        if current and current.strip() and not owned or "solution" in edited_fields(pid):
            continue
        text = MARKER + "\n\n" + dedent(body).strip()
        count += 1
        if write:
            if owned:
                con.execute("UPDATE problems SET solution=? WHERE id=?", (text, pid))
            else:
                con.execute("""UPDATE problems SET solution=?,
                    review_notes=COALESCE(review_notes,'') || ?,extraction_status='needs_review'
                    WHERE id=? AND (solution IS NULL OR trim(solution)='')""",
                    (text, " solution: редакция ИИ по исходному условию; требуется проверка.", pid))
    return count


if __name__ == "__main__":
    with sqlite3.connect(DB) as connection:
        print(f"Completed 2025 AI TeX solutions: {run(connection, write=True)}")
